function ensureHD(i){if(hdCache.has(i)||loading.has(i))return;loading.add(i);new THREE.TextureLoader().load(MAPS[i].hd,t=>{loading.delete(i);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());artMeshes[i].material.map=t;artMeshes[i].material.needsUpdate=true;hdCache.set(i,t);if(hdCache.size>6){const old=[...hdCache.keys()].find(k=>k!==i&&k!==focus);if(old!==undefined){artMeshes[old].material.map=previews[old];artMeshes[old].material.needsUpdate=true;hdCache.get(old).dispose();hdCache.delete(old)}}},undefined,()=>loading.delete(i))}
