function drawPlan(){const c=$('#floorplan'),ctx=c.getContext('2d');ctx.clearRect(0,0,220,210);const room=Math.min(2,Math.max(0,Math.floor(-player.z/30)));const roomTitles=hallTitles.map((s,i)=>'0'+(i+1)+' · '+s);$('#roomName').textContent=roomTitles[room];$('#roomBadge').textContent=hallTitles[room];for(let r=0;r<3;r++){ctx.fillStyle=r===room?'#516c65':'#2c4848';ctx.fillRect(60,8+r*64,100,60);ctx.strokeStyle='#a9b2a055';ctx.strokeRect(60,8+r*64,100,60);ctx.fillStyle='#d7c294';ctx.font='13px sans-serif';ctx.fillText('0'+(r+1),25,43+r*64)}MAPS.forEach((m,i)=>{const p=posFor(i),x=p.left?66:154,y=8+(-p.z/90)*192;ctx.beginPath();ctx.arc(x,y,3.4,0,Math.PI*2);ctx.fillStyle=inspected.has(i)?'#d9b776':'#a8b7ad';ctx.fill()});for(const s of studyIslands){ctx.fillStyle='#e0be6e';ctx.fillRect(103,8+(-s.z/90)*192-4,14,8)}const x=110+player.x/18*100,y=8+(-player.z/90)*192;ctx.save();ctx.translate(x,y);ctx.rotate(yaw);ctx.fillStyle='#f8ead0';ctx.beginPath();ctx.moveTo(0,7);ctx.lineTo(-4,-4);ctx.lineTo(4,-4);ctx.closePath();ctx.fill();ctx.restore()}
