const storageKey='beijing-map-museum-v3';
function saveProgress(){try{localStorage.setItem(storageKey,JSON.stringify({version:3,visited:[...inspected],favourites:[...favourites],discoveries:[...discoveries],settings}))}catch{}}
function cleanIds(a){return (Array.isArray(a)?a:[]).filter(x=>Number.isInteger(x)&&x>=0&&x<30)}
function applyProgress(d){inspected=new Set(cleanIds(d.visited));favourites=new Set(cleanIds(d.favourites));discoveries=new Set((Array.isArray(d.discoveries)?d.discoveries:[]).filter(x=>typeof x==='string'&&/^\d{2}-[0-2]$/.test(x)&&MAPS.some(m=>m.id===x.split('-')[0]&&m.hotspots?.[Number(x.split('-')[1])])));if(d.settings){settings.quality=['low','balanced','high'].includes(d.settings.quality)?d.settings.quality:'balanced';settings.sensitivity=Math.max(.4,Math.min(2,Number(d.settings.sensitivity)||1));settings.reduced=!!d.settings.reduced}}
