function enterInspect(i){if(!camera)return;if(inspectMode&&focus===i)return;exitInspect();inspectSaved={position:player.clone(),yaw,pitch,viewMode};focus=i;inspected.add(i);saveProgress();inspectMode=true;clearMotion();ensureHD(i);$('#inspectBar').hidden=false;$('#inspectBtn').hidden=true;$('#crosshair').hidden=true;fitInspectCamera();}
