function planPath(tx,tz){const step=.6,toCell=(x,z)=>[Math.round(x/step),Math.round(z/step)],key=(x,z)=>x+','+z;let [sx,sz]=toCell(player.x,player.z),[ex,ez]=toCell(tx,tz);if(blocked(ex*step,ez*step))return [];const start=key(sx,sz),end=key(ex,ez),q=[[sx,sz]],from=new Map([[start,null]]);for(let at=0;at<q.length&&at<10000;at++){const [x,z]=q[at],k=key(x,z);if(k===end){const result=[];let cur=k;while(cur!==start){const [xx,zz]=cur.split(',').map(Number);result.push({x:xx*step,z:zz*step});cur=from.get(cur)}return result.reverse()}for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,nz=z+dz,nk=key(nx,nz);if(!from.has(nk)&&!blocked(nx*step,nz*step)){from.set(nk,k);q.push([nx,nz])}}}return []}
