function bindJoystick(id,look){const el=$('#'+id),knob=el.querySelector('span');let active=null;const reset=()=>{active=null;knob.style.transform='translate(0px,0px)';if(look)joyTurn={x:0,y:0};else moveStick={}};const change=e=>{if(e.pointerId!==active)return;const r=el.getBoundingClientRect(),x=Math.max(-1,Math.min(1,(e.clientX-r.left-r.width/2)/35)),y=Math.max(-1,Math.min(1,(e.clientY-r.top-r.height/2)/35));knob.style.transform=`translate(${x*30}px,${y*30}px)`;if(look)joyTurn={x,y};else {autoPath=[];moveStick={forward:y<-.2,backward:y>.2,left:x<-.2,right:x>.2}}};el.onpointerdown=e=>{if(!started||modalOpen())return;e.preventDefault();active=e.pointerId;el.setPointerCapture(active);change(e)};el.onpointermove=change;el.onpointerup=reset;el.onpointercancel=reset;el.onlostpointercapture=reset;window.addEventListener('blur',reset)}
const tourStops=[1,23,14,10,24,17];function startTour(){exitInspect();tour={step:0,paused:true};$('#tourBar').hidden=false;showGuideStop()}
function nextTour(){if(!tour)return;tour.step++;if(tour.step>=window.CURATION.stops.length){endTour();toast('六次选择，留下一种属于你的观看方式。可在护照里保存纪念。');return}showGuideStop()}
