function updateV3(dt,t){if(!modalOpen()&&!inspectMode){yaw-=joyTurn.x*dt*1.8*settings.sensitivity;pitch=THREE.MathUtils.clamp(pitch-joyTurn.y*dt*1.1*settings.sensitivity,-1.1,1.1)}if(avatar&&photoMode){avatarParts.rightArm.rotation.z=photoPose===1?-2.3:photoPose===2?-1.1:0;avatarParts.leftArm.rotation.z=photoPose===2?1.1:0}else if(avatar){avatarParts.rightArm.rotation.z=0;avatarParts.leftArm.rotation.z=0}if(settings.reduced&&dust)dust.position.y=0;if(inspectMode)$('#inspectBtn').hidden=true;if(tour){if(tour)$('#tourLabel').textContent=`精选 ${tour.step+1}/6 · ${MAPS[tourStops[tour.step]].title}`}
 if(expRenderer&&$('#experienceDialog').open&&expGroup){expGroup.rotation.y=expYaw;expParts.forEach((o,i)=>{o.position.y=o.userData.baseY+expSpread*(o.userData.lift||0)});updateCourtyardV4(dt);expRenderer.render(expScene,expCamera)}
}
function renderArtExtras(){let wrap=$('#artExtras');if(!wrap){wrap=document.createElement('section');wrap.id='artExtras';$('.art-copy').insertBefore(wrap,$('.art-nav'))}wrap.replaceChildren();const title=document.createElement('h3');title.textContent='发现画面里的细节';wrap.append(title);const points=(MAPS[current].hotspots||[]);if(points.length){const list=document.createElement('div');list.className='hotspot-list';points.forEach((p,k)=>{const b=document.createElement('button');b.textContent=(discoveries.has(MAPS[current].id+'-'+k)?'✓ ':'')+(k+1)+' · '+p.title;b.onclick=()=>{const im=$('#detailImage');imageZoom=2.4;imageX=(.5-p.x)*im.clientWidth*imageZoom;imageY=(.5-p.y)*im.clientHeight*imageZoom;constrainImage();imageTransform();discoveries.add(MAPS[current].id+'-'+k);saveProgress();note.textContent=p.text;b.textContent='✓ '+(k+1)+' · '+p.title};list.append(b)});const note=document.createElement('p');note.className='hotspot-note';note.textContent='选择一个观察点，放大对应细节。';wrap.append(list,note)}else{const note=document.createElement('p');note.textContent='先看画面如何组织点、线与留白，再比较色彩与材质的表达。';wrap.append(note)}const actions=document.createElement('div');actions.className='extra-actions';const fav=document.createElement('button');fav.textContent=favourites.has(current)?'已收藏 · 取消':'收藏作品';fav.onclick=()=>{favourites.has(current)?favourites.delete(current):favourites.add(current);saveProgress();renderArtExtras()};const cmp=document.createElement('button');cmp.textContent='双图对照';cmp.onclick=()=>openCompare(current);actions.append(fav,cmp);if([1,14,16].includes(current)){const play=document.createElement('button');play.textContent='体验地图互动';play.onclick=()=>openExperience(current);actions.append(play)}wrap.append(actions)}
function openCompare(i){const pair=window.CURATION?.pairs.find(p=>p.mapIds.includes(MAPS[i].id));$('#compareA').value=i;$('#compareB').value=pair?Number(pair.mapIds.find(id=>id!==MAPS[i].id))-1:(i+1)%30;$('#comparePrompt').textContent=pair?.question||'比较两幅作品怎样组织线条、颜色与留白。';for(const s of ['A','B'])$('#compareImage'+s).src=MAPS[+$('#compare'+s).value].hd;openDialog('compareDialog')}
function renderPassport(){const grid=$('#passportGrid');grid.replaceChildren();$('#passportSummary').textContent=`已看 ${inspected.size}/30 幅 · 收藏 ${favourites.size} 幅 · 发现 ${discoveries.size} 处细节`;MAPS.forEach((m,i)=>{const b=document.createElement('button');b.className=inspected.has(i)?'stamp visited':'stamp';b.textContent=(favourites.has(i)?'★ ':'')+'DAY '+m.id;b.title=m.title;b.onclick=()=>{$('#passportDialog').close();showArt(i)};grid.append(b)})}
