function downloadBlob(data,name,type){const u=URL.createObjectURL(new Blob([data],{type}));downloadURL(u,name);setTimeout(()=>URL.revokeObjectURL(u),2000)}
async function createPostcard(){const ids=[...favourites,...inspected].filter((x,i,a)=>a.indexOf(x)===i).slice(0,3);if(!ids.length){toast('先欣赏或收藏一幅作品，再生成明信片');return}const c=document.createElement('canvas');c.width=1500;c.height=1000;const ctx=c.getContext('2d');ctx.fillStyle='#eeeae0';ctx.fillRect(0,0,1500,1000);ctx.fillStyle='#203d3e';ctx.font='bold 64px sans-serif';ctx.fillText('北京的三十种面孔',80,120);ctx.font='28px sans-serif';ctx.fillText('我的观展明信片 · '+new Date().toLocaleDateString('zh-CN'),80,175);for(let n=0;n<ids.length;n++){const m=MAPS[ids[n]],img=await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>resolve(null);im.src=m.hd});if(!img)continue;const boxW=400,boxH=590,scale=Math.min(boxW/img.width,boxH/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,80+n*470+(boxW-w)/2,240+(boxH-h)/2,w,h);ctx.fillStyle='#203d3e';ctx.font='22px sans-serif';ctx.fillText('DAY '+m.id+' · '+m.title,80+n*470,880,420)}ctx.font='20px sans-serif';ctx.fillText('所有地图皆为AI创作，请勿与实际地理空间对应。',80,950);downloadURL(c.toDataURL('image/png'),'北京地图_我的观展明信片.png')}
